# Parse the raw ATC/DDD HTML snapshots downloaded by the bronze script.
# This script was generated by AI

library(rvest)
library(dplyr)
library(readr)

bronze_dir <- "./src/1 bronze/staging area/atc_ddd"
silver_dir <- "./src/2 silver/staging area"
if (!dir.exists(bronze_dir)) {
  stop("Bronze HTML snapshots not found. Run 06_scrape_atc_ddd.R first: ", bronze_dir)
}
dir.create(silver_dir, recursive = TRUE, showWarnings = FALSE)

extract_codes <- function(page) {
  links <- html_elements(page, "a[href*=code]")
  hrefs <- html_attr(links, "href")
  names <- html_text2(links)
  keep <- !is.na(hrefs) & !is.na(names) & names != "Show text from Guidelines"
  hrefs <- hrefs[keep]
  names <- names[keep]
  codes <- sub(".*[?&]code=([^&]+).*", "\\1", hrefs)
  tibble(atc_name = names, atc_code = codes, level = nchar(codes))
}

html_files <- list.files(bronze_dir, pattern = "\\.html$", full.names = TRUE)
pages <- lapply(html_files, read_html)
atc_list <- bind_rows(lapply(pages, extract_codes)) %>%
  distinct() %>%
  arrange(atc_code)

extract_ddd_table <- function(page) {
  table <- html_element(page, "div#content table")
  if (is.na(table)) return(NULL)

  rows <- html_elements(table, "tr")
  if (length(rows) < 2) return(NULL)
  cells <- lapply(rows, function(row) {trimws(html_text2(html_elements(row, "td")))})
  headers <- cells[[1]]
  body <- cells[-1]
  body <- body[lengths(body) == length(headers)]
  if (!length(body)) return(NULL)
  result <- as.data.frame(do.call(rbind, body), stringsAsFactors = FALSE)
  names(result) <- headers
  result
}

# DDD tables are on ATC pages whose code has length 5.
ddd_files <- html_files[basename(html_files) %in% paste0(atc_list$atc_code[atc_list$level == 5], ".html")]
ddd_tables <- lapply(ddd_files, function(path) extract_ddd_table(read_html(path)))
ddd_tables <- Filter(Negate(is.null), ddd_tables)
if (!length(ddd_tables)) stop("No DDD tables found in the bronze HTML snapshots.")

atc_ddd <- bind_rows(ddd_tables) %>%
  mutate(across(everything(), ~ na_if(.x, ""))) %>%
  tidyr::fill(`ATC code`, Name, .direction = "down") %>%
  filter(!is.na(DDD))

write_delim(atc_list, file.path(silver_dir, "atc_list.csv"), delim = "|", na = "")
write_delim(atc_ddd, file.path(silver_dir, "atc_ddd.csv"), delim = "|", na = "")
message("Wrote ATC hierarchy and DDD tables to ", silver_dir)
